mapper.select:
SELECT mkt03_history_id AS history_id , mkt03_person_id AS person_id , mkt03_reg_date::date AS reg_date , mkt03_target_company_id AS target_company_id , mkt03_target_company_nm AS target_company_name , mkt03_activity_date::date AS activity_date , mkt03_activity_title AS activity_title , mkt03_activity_content AS activity_content , mkt03_person_org_nm AS person_org_name , mkt03_file_count AS file_count , mkt03_fund_info AS fund_info , mkt03_share_info AS share_info FROM (
SELECT mkt03_history.* , f_emp_kor_nm(mkt03_person_id) AS mkt03_person_nm , f_get_empTrans(mkt03_person_id, mkt03_activity_date, 'person_org_info') AS mkt03_person_org_nm , mkt01_target_company_nm AS mkt03_target_company_nm , fund_info AS mkt03_fund_info , ( SELECT COUNT(*)||'건' FROM sys10_file WHERE sys10_parent_id = mkt03_history_id ) AS mkt03_file_count , ( SELECT (SELECT CASE WHEN mkt05_share_cd = '1' THEN f_emp_kor_nm(mkt05_person_id) ELSE f_org_nm(mkt05_org_id, f_today()) END FROM mkt05_share WHERE mkt05_parent_id = mkt03_history_id ORDER BY mkt05_share_cd DESC LIMIT 1) ||(CASE WHEN COUNT(*) = 1 THEN '' ELSE ' 외 '|| COUNT(*)-1 END) FROM mkt05_share WHERE mkt05_parent_id = mkt03_history_id ) AS mkt03_share_info FROM mkt03_history INNER JOIN mkt01_target_company ON mkt01_target_company_id = mkt03_target_company_id LEFT OUTER JOIN ( SELECT mkt04_history_id as history_id , MAX(fnd02_fund_nm) || CASE WHEN COUNT(*) = 1 THEN '' ELSE ' 외 ' || (COUNT(*) - 1) END as fund_info FROM mkt04_relate_fund INNER JOIN fnd02_fund_info ON ( fnd02_fund_code_id = mkt04_fund_id AND fnd02_work_date = ( SELECT MAX(fnd02_work_date) FROM fnd02_fund_info WHERE fnd02_fund_code_id = mkt04_fund_id AND fnd02_work_date <= f_today() )) WHERE mkt04_company_id = #{companyId} GROUP BY mkt04_history_id ) fnd ON history_id = mkt03_history_id WHERE mkt03_company_id = #{companyId}
AND mkt03_reg_date BETWEEN #{stdDate}::date AND #{stdDate}::date
AND ( #{personId} IN ( SELECT mkt03_person_id UNION ALL SELECT mkt05_person_id FROM mkt05_share WHERE mkt05_share_cd = '1' AND mkt05_parent_id = mkt03_history_id ) OR #{orgId} IN ( SELECT mkt05_org_id FROM mkt05_share WHERE mkt05_share_cd = '2' AND mkt05_parent_id = mkt03_history_id ) )
) mkt03 ORDER BY mkt03_activity_title COLLATE "ko_KR.utf8"

SELECT ROW_NUMBER() OVER() AS row_id , emp20_leave_id AS leave_id , emp20_leave_cd AS leave_code , emp20_person_nm AS person_name , emp20_leave_nm AS leave_name , emp20_std_period AS std_period FROM (
-------------------------------------- -- 휴가 -------------------------------------- SELECT emp20_leave_id , f_emp_kor_nm(emp20_person_id) ||'('||f_get_empTrans(emp20_person_id, emp20_reg_date, 'org_code_nm')||')' AS emp20_person_nm , '11010' AS emp20_leave_cd , f_cdnm('leaveCode', emp20_leave_cd, emp20_company_id, emp20_reg_date) ||CASE WHEN emp20_leave_cd = '04' AND COALESCE(emp20_spc_leave_cd,'') != '' THEN '('||f_cdnm('SpecialLeaveCode', emp20_spc_leave_cd, emp20_company_id, emp20_reg_date)||')' ELSE '' END AS emp20_leave_nm , CASE WHEN emp20_start_date = emp20_close_date THEN emp20_start_date||'' ELSE emp20_start_date||' ~ '||emp20_close_date END AS emp20_std_period , emp20_manager_nm , emp20_start_date , emp20_close_date FROM emp20_leave INNER JOIN apr01_appr ON ( apr01_appr_id = emp20_appr_id AND apr01_status_cd NOT IN ('99','40') ) WHERE emp20_company_id = #{companyId} AND emp20_start_date <= #{stdDate} AND emp20_close_date >= #{stdDate} AND COALESCE(emp20_cancel,'false') != 'true' -------------------------------------- -- 출장 -------------------------------------- UNION ALL SELECT emp53_biz_trip_id AS emp20_leave_id , f_emp_kor_nm(emp53_person_id) ||'('||f_get_empTrans(emp53_person_id, emp53_start_date, 'org_code_nm')||')' AS emp20_person_nm , '11020' AS emp20_leave_cd , f_cdnm('BizTripCode', emp53_biz_trip_cd, emp53_company_id, emp53_start_date) ||' - '||emp53_destination AS emp20_leave_nm , CASE WHEN emp53_start_date = emp53_close_date THEN emp53_start_date||'' ELSE emp53_start_date||' ~ '||emp53_close_date END AS emp20_std_period , '' AS emp20_manager_nm , emp53_start_date AS emp20_start_date , emp53_close_date AS emp20_close_date FROM emp53_biz_trip INNER JOIN apr01_appr ON ( apr01_appr_id = emp53_appr_id AND apr01_status_cd NOT IN ('99','40') ) WHERE emp53_company_id = #{companyId} AND emp53_start_date <= #{stdDate} AND emp53_close_date >= #{stdDate}
AND ( ( COALESCE(emp53_public_yn,'false') != 'true' AND ( #{personId} IN ( SELECT emp53_person_id UNION ALL SELECT UNNEST(ARRAY[apr04_step_emp_id, apr04_appr_emp_id]) FROM apr04_appr_step WHERE apr04_appr_id = emp53_appr_id UNION ALL SELECT emp56_person_id FROM emp56_share WHERE emp56_parent_id = emp53_biz_trip_id AND emp56_share_cd = '1' ) OR #{orgId} IN ( SELECT emp56_org_id FROM emp56_share WHERE emp56_parent_id = emp53_biz_trip_id AND emp56_share_cd = '2' ) ) ) OR ( COALESCE(emp53_public_yn,'false') = 'true' ) )
-------------------------------------- -- 외출 -------------------------------------- UNION ALL SELECT emp54_errand_id AS emp20_leave_id , f_emp_kor_nm(emp54_person_id) ||'('||f_get_empTrans(emp54_person_id, emp54_date, 'org_code_nm')||')' AS emp20_person_nm , '11030' AS emp20_leave_cd , CONCAT('외출 - ' ,CASE WHEN emp54_errand_cd = '9' THEN '' ELSE f_cdnm('ErrandCode', emp54_errand_cd, emp54_company_id, emp54_date) END ,' '||trim(emp54_reason) ,' (장소:'||trim(emp54_venue)||')' ) AS emp20_leave_nm , emp54_depart_time||' ~ '||emp54_return_time AS emp20_std_period , '' AS emp20_manager_nm , emp54_date AS emp20_start_date , emp54_date AS emp20_close_date FROM emp54_errand WHERE emp54_company_id = #{companyId} AND emp54_date BETWEEN #{stdDate} AND #{stdDate}
AND ( ( COALESCE(emp54_public_yn,'false') != 'true' AND ( #{personId} IN ( SELECT emp54_person_id UNION ALL SELECT UNNEST(ARRAY[apr04_step_emp_id, apr04_appr_emp_id]) FROM apr04_appr_step WHERE apr04_appr_id = emp54_appr_id UNION ALL SELECT emp56_person_id FROM emp56_share WHERE emp56_parent_id = emp54_errand_id AND emp56_share_cd = '1' ) OR #{orgId} IN ( SELECT emp56_org_id FROM emp56_share WHERE emp56_parent_id = emp54_errand_id AND emp56_share_cd = '2' ) ) ) OR ( COALESCE(emp54_public_yn,'false') = 'true' ) )
) t

SELECT ROW_NUMBER() OVER() AS row_id , mrb01_booking_id AS booking_id , mrb01_emp_id AS emp_id , mrb01_emp_nm AS emp_name , mrb01_content AS content , mrb01_attendance AS attendance , mrb01_booking_dt::date AS booking_date , mrb01_time AS time , mrb01_type AS type , mrb01_type_nm AS type_name FROM (
------------------------------------- -- 회의실 예약 ------------------------------------- SELECT mrb01_booking_id AS mrb01_booking_id , mrb01_emp_id AS mrb01_emp_id , f_emp_kor_nm(mrb01_emp_id) ||'('||f_get_empTrans(mrb01_emp_id, mrb01_booking_dt::date, 'org_code_nm')||')' AS mrb01_emp_nm , f_cdnm('MeetingRoomCode', mrb01_room_cd, mrb01_company_id, mrb01_booking_dt) ||' - '||mrb01_subject AS mrb01_content , mrb01_attendance AS mrb01_attendance , mrb01_booking_dt AS mrb01_booking_dt , mrb01_start_hour||':'||mrb01_start_min||' ~ '||mrb01_close_hour||':'||mrb01_close_min AS mrb01_time , '12010' AS mrb01_type , '회의실' AS mrb01_type_nm , 1 AS seq FROM mrb01_booking WHERE mrb01_company_id = #{companyId} AND mrb01_booking_dt BETWEEN #{stdDate} AND #{stdDate} ------------------------------------- -- 공용차량 예약 ------------------------------------- UNION ALL SELECT car03_booking_id AS mrb01_booking_id , car03_person_id AS mrb01_emp_id , f_emp_kor_nm(car03_person_id) ||'('||f_get_empTrans(car03_person_id, car03_start_date, 'org_code_nm')||')' AS mrb01_emp_nm , car01_car_nm||' - '||car03_destination AS mrb01_content , car03_attendance AS mrb01_attendance , car03_start_date AS mrb01_booking_dt , car03_start_hour||':'||car03_start_min||' ~ '||car03_close_hour||':'||car03_close_min AS mrb01_time , '12020' AS mrb01_type , '공용차량' AS mrb01_type_nm , 2 AS seq FROM car03_booking INNER JOIN car01_info ON ( car01_info_id = car03_info_id AND car01_car_type = '2' AND car01_company_id = #{companyId} ) WHERE car03_start_date BETWEEN #{stdDate} AND #{stdDate}
) t ORDER BY seq, mrb01_time
